class AuditLog:
    """Records every event it is given, so tests can see what was delivered."""

    def __init__(self):
        self.events = []

    def __call__(self, payload):
        self.events.append(payload)


class Mailbox:
    def __init__(self):
        self.messages = []

    def __call__(self, payload):
        self.messages.append("welcome %s" % payload["user"])

