from bus import EventBus
from handlers import AuditLog, Mailbox


class Tenant:
    """One customer of ours. Each tenant has its own bus, so one tenant's events never reach another's handlers."""

    def __init__(self, name):
        self.name = name
        self.bus = EventBus()
        self.audit = AuditLog()
        self.mailbox = Mailbox()
        self.bus.subscribe("signup", self.audit)

    def enable_welcome_email(self):
        self.bus.subscribe("signup", self.mailbox)

    def sign_up(self, user):
        return self.bus.publish("signup", {"user": user, "tenant": self.name})

    def signups(self):
        return [event["user"] for event in self.bus.replay("signup")]

